        if not _is_number(item):
            raise TypeError(
                f"{name}[{r}] must be an int or float, "
                f"got {type(item).__name__}"
            )
        try:
            value = float(item)
        except OverflowError:
            raise ValueError(
                f"{name}[{r}] must be finite, got {item!r}"
            ) from None
        _check_finite(f"{name}[{r}]", value)
